<?php
declare(strict_types=1);require_once __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/Modules/QRExperience/helpers.php';qrx_require_admin();$pdo=db();$message='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
 if($action==='delete'&&$id){$pdo->prepare('DELETE FROM qr_experience_campaigns WHERE id=?')->execute([$id]);$message='Kampanya silindi.';}
 elseif($action==='toggle'&&$id){$pdo->prepare('UPDATE qr_experience_campaigns SET is_active=1-is_active,updated_at=NOW() WHERE id=?')->execute([$id]);$message='Kampanya durumu değiştirildi.';}
 elseif($action==='duplicate'&&$id){$pdo->prepare("INSERT INTO qr_experience_campaigns(title,subtitle,button_text,button_url,background_color,text_color,is_active,starts_at,ends_at,sort_order,media_type,media_url,updated_at) SELECT CONCAT(title,' (Kopya)'),subtitle,button_text,button_url,background_color,text_color,0,starts_at,ends_at,sort_order,media_type,media_url,NOW() FROM qr_experience_campaigns WHERE id=?")->execute([$id]);$message='Kampanya çoğaltıldı.';}
 else{$data=[trim((string)($_POST['title']??'')),trim((string)($_POST['subtitle']??'')),trim((string)($_POST['button_text']??'')),trim((string)($_POST['button_url']??'')),(string)($_POST['background_color']??'#d71920'),(string)($_POST['text_color']??'#ffffff'),isset($_POST['is_active'])?1:0,($_POST['starts_at']??'')?:null,($_POST['ends_at']??'')?:null,(int)($_POST['sort_order']??0),(string)($_POST['media_type']??'none'),trim((string)($_POST['media_url']??''))];
  if($id){$data[]=$id;$pdo->prepare('UPDATE qr_experience_campaigns SET title=?,subtitle=?,button_text=?,button_url=?,background_color=?,text_color=?,is_active=?,starts_at=?,ends_at=?,sort_order=?,media_type=?,media_url=?,updated_at=NOW() WHERE id=?')->execute($data);$message='Kampanya güncellendi.';}
  else{$pdo->prepare('INSERT INTO qr_experience_campaigns(title,subtitle,button_text,button_url,background_color,text_color,is_active,starts_at,ends_at,sort_order,media_type,media_url,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute($data);$message='Kampanya oluşturuldu.';}}
}
if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM qr_experience_campaigns WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=qrx_campaigns(false,$pdo);
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing Studio</title><link rel="stylesheet" href="assets/studio.css"><link rel="stylesheet" href="/admin/enterprise/assets/media-picker.css?v=720"></head><body class="page"><header class="simple"><a href="index.php">← Dashboard</a><h1>Marketing Studio</h1><p>Zamanlanmış banner, görsel ve video kampanyaları.</p></header><main class="component-grid"><?php if($message):?><div class="notice"><?=e($message)?></div><?php endif;?><section class="panel"><h2><?=$edit?'Kampanyayı Düzenle':'Yeni Kampanya'?></h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Başlık<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Alt metin<textarea name="subtitle"><?=e($edit['subtitle']??'')?></textarea></label><div class="two"><label>Buton metni<input name="button_text" value="<?=e($edit['button_text']??'')?>"></label><label>Buton bağlantısı<input name="button_url" value="<?=e($edit['button_url']??'')?>" placeholder="/menu veya https://..."></label><label>Medya türü<select name="media_type"><option value="none">Yok</option><option value="image" <?=($edit['media_type']??'')==='image'?'selected':''?>>Görsel / GIF</option><option value="video" <?=($edit['media_type']??'')==='video'?'selected':''?>>Video</option></select></label><label>Medya URL<input name="media_url" value="<?=e($edit['media_url']??'')?>" placeholder="https://..."></label><label>Arka plan<input type="color" name="background_color" value="<?=e($edit['background_color']??'#d71920')?>"></label><label>Metin rengi<input type="color" name="text_color" value="<?=e($edit['text_color']??'#ffffff')?>"></label><label>Başlangıç<input type="datetime-local" name="starts_at" value="<?=!empty($edit['starts_at'])?e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):''?>"></label><label>Bitiş<input type="datetime-local" name="ends_at" value="<?=!empty($edit['ends_at'])?e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):''?>"></label><label>Sıra<input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label></div><label><input type="checkbox" name="is_active" <?=!$edit||!empty($edit['is_active'])?'checked':''?>> Aktif</label><div class="row-actions"><button>Kaydet</button><?php if($edit):?><a class="button secondary" href="marketing.php">Vazgeç</a><?php endif;?></div></form></section><section class="panel"><h2>Kampanyalar</h2><?php foreach($rows as $r):?><div class="campaign-row"><div class="campaign-info"><b><?=e($r['title'])?></b><small><?=e($r['subtitle']??'')?> · <?=$r['is_active']?'Aktif':'Pasif'?> · <?=e($r['media_type']??'none')?></small></div><div class="row-actions"><a class="button mini secondary" href="?edit=<?=$r['id']?>">Düzenle</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="mini" name="action" value="toggle">Aç/Kapat</button><button class="mini" name="action" value="duplicate">Çoğalt</button><button class="danger mini" name="action" value="delete" onclick="return confirm('Silinsin mi?')">Sil</button></form></div></div><?php endforeach;?><?php if(!$rows):?><p>Henüz kampanya yok.</p><?php endif;?></section></main><script src="/admin/enterprise/assets/media-picker.js?v=720"></script></body></html>
